// Original BCS preliminary practice sets written by the Grontho Bilash team.
// These are practice questions on the preliminary syllabus areas, NOT past
// BCS papers, and are labelled that way wherever they are shown. Questions
// stick to settled facts; nothing depends on current affairs.
//
// Each question: [question, [ক, খ, গ, ঘ], index of the correct option, explanation]

type Q = [string, [string, string, string, string], 0 | 1 | 2 | 3, string];

export interface PracticeSet {
  slug: string;
  title: string;
  summary: string;
  subject: string;
  tags: string[];
  questions: Q[];
}

const LETTERS = ["ক", "খ", "গ", "ঘ"];
const BN = "০১২৩৪৫৬৭৮৯";
const bn = (n: number) => String(n).replace(/\d/g, (d) => BN[Number(d)]);

// Markdown body: question, options, then the answer in a quote block (the
// site shows it behind "উত্তর ও ব্যাখ্যা দেখো").
export const practiceBody = (set: PracticeSet) =>
  [
    `> এটি গ্রন্থবিলাস টিমের তৈরি **অনুশীলনী** (বিসিএস প্রিলিমিনারির সিলেবাস অনুযায়ী)। এগুলো বিগত সালের প্রশ্ন নয়। আগে নিজে উত্তর দাও, তারপর "উত্তর ও ব্যাখ্যা দেখো" চাপো।`,
    "",
    ...set.questions.flatMap(([q, options, answer, why], i) => [
      `### ${bn(i + 1)}. ${q}`,
      "",
      ...options.map((o, j) => `- (${LETTERS[j]}) ${o}`),
      "",
      `> **উত্তর: (${LETTERS[answer]}) ${options[answer]}**`,
      `>`,
      `> ${why}`,
      "",
    ]),
  ].join("\n");

